import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/users.db'
SECRET = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department. Requires valid HMAC token."""
    token = request.headers.get('X-Auth-Token', '')
    username = request.headers.get('X-Username', '')

    # Verify HMAC authentication
    expected = hmac.new(SECRET.encode(), username.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(token, expected):
        return jsonify({'error': 'unauthorized'}), 401

    department = request.args.get('dept', '')
    include_email = request.args.get('include_email', 'false')

    # Build query with department filter
    if include_email == 'true':
        query = f"SELECT username, email, department FROM users WHERE department = '{department}'"
    else:
        query = f"SELECT username, department FROM users WHERE department = '{department}'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute(
            "INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)",
            ('user_search', username, department)
        )
        db.commit()
        return jsonify({'users': users})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID. Uses parameterized query."""
    db = get_db()
    user = db.execute('SELECT username, department, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user. Admin only."""
    token = request.headers.get('X-Auth-Token', '')
    username = request.headers.get('X-Username', '')

    expected = hmac.new(SECRET.encode(), username.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(token, expected):
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    actor = db.execute('SELECT role FROM users WHERE username = ?', (username,)).fetchone()
    if not actor or actor['role'] != 'admin':
        return jsonify({'error': 'forbidden'}), 403

    data = request.get_json()
    pw_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    db.execute(
        'INSERT INTO users (username, email, password_hash, role, department) VALUES (?, ?, ?, ?, ?)',
        (data['username'], data['email'], pw_hash, data.get('role', 'user'), data['department'])
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
